    val MAP: Map<String, DuaText> = mapOf(
        "dua_sharri_sami" to DuaText("Duyularımın Kötülüğünden Sığınırım", "Allah'ım, kulağımın şerrinden, gözümün şerrinden, dilimin şerrinden, kalbimin şerrinden ve nefsimin şerrinden sana sığınırım.", "Shakal ibn Humayd (RA)'ya öğretti.", "Uzuvları ve nefsi günahlardan korumak için yapılan dua."),
